fn seal(){fn walk(p:&Path,b:&Path,out:&mut BTreeMap<String,String>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,b,out)}else{let f=p.strip_prefix(b).unwrap().display().to_string();if f!="SHA256SUMS"&&f!="artifact-index.json"{out.insert(f,hash(&p));}}}}let base=Path::new(D);let mut files=BTreeMap::new();walk(base,base,&mut files);save(base.join("artifact-index.json"),&json!(files));files.insert("artifact-index.json".into(),hash(base.join("artifact-index.json")));fs::write(base.join("SHA256SUMS"),files.iter().map(|(f,h)|format!("{h}  {f}\n")).collect::<String>()).unwrap();for(f,h)in &files{assert_eq!(hash(base.join(f)),*h);}println!("Sealed {} hashes / {} files",files.len(),files.len()+1);}
